#include "unity.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_buffer_append_appends_string_to_nonempty_buffer(void) {
    // Setup: create a buffer with initial data
    buffer_t *buf = helper_make_buffer_with_data("Hello");
    const char *to_append = " World";

    // Test: append a string to the buffer
    int result = buffer_append(buf, to_append);

    // Assertions
    TEST_ASSERT_EQUAL(0, result);
    helper_assert_buffer_data_equals(buf, "Hello World");
    helper_assert_buffer_length(buf, 11);

    // Cleanup
    buffer_free(buf);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_buffer_append_appends_string_to_nonempty_buffer);
    return UNITY_END();
}
